    } else {
        snprintf(event, cap, "move");
        return 0;
    }
    spawn_food(g);
    if (g->status == 2) {
        snprintf(event, cap, "%s; won", ev);
    } else {
        snprintf(event, cap, "%s; food %d,%d %s", ev, g->fr, g->fc, g->fkind ? "pepper" : "apple");
    }
    return 0;
}

void coil_render(const Coil *g, char *out, size_t cap) {
    size_t n = 0;
